_MODE_INDEX = {"low": 0, "medium": 1, "high": 2}
_AUDIENCE_KEYS = {
    "engineers": "engineers",
    "investors": "investors",
    "students": "students",
    "general public": "general_public",
}


def normalize_fallback_language(language):
    return normalize_language(language)


def _format(value, context):
    return value.format(**context)


def _localized_option(kind, value, language, default):
    normalized = " ".join(str(value or "").split()).casefold()
    if kind == "category" and normalized in {
        "transport", "construction", "rescue", "military", "exploration",
        "industrial", "energy", "architecture", "mechanical", "water",
        "flight", "space", "agriculture", "medicine", "robotics",
    }:
        return translate(f"option.category.{normalized}", language)
    if kind == "audience" and normalized in _AUDIENCE_KEYS:
        return translate(f"option.audience.{_AUDIENCE_KEYS[normalized]}", language)
    return " ".join(str(value or "").split()) or default


def build_localized_fallback_concept(
    *,
    language,
    category,
    prompt_text,
    creativity_mode,
    audience,
    mode,
    difficulty,
    modern_difficulty,
):
    language = normalize_fallback_language(language)
    pack = {**_ENGLISH_PACK, **_PACKS.get(language, {})}
    default_prompt, default_audience, default_category = pack["defaults"]
    prompt = " ".join(str(prompt_text or "").split()) or default_prompt
    audience_text = _localized_option("audience", audience, language, default_audience)
    category_text = _localized_option("category", category, language, default_category)
    mode_label = pack["modes"][_MODE_INDEX[mode]]
    concept_suffix, pilot_suffix = pack["suffixes"]
    title_words = prompt.split()
    title_fragment = " ".join(title_words[:9]) + ("…" if len(title_words) > 9 else "")
    if title_fragment:
        title_fragment = title_fragment[0].upper() + title_fragment[1:]
    context = {
        "prompt": prompt,
        "audience": audience_text,
        "category": category_text,
        "mode": mode_label,
        "mode_cap": mode_label[:1].upper() + mode_label[1:],
    }
    optional_count = _MODE_INDEX[mode] + 1
    components = [_format(item, context) for item in pack["components"]]
    components.extend(
        _format(pack["optional"], {**context, "index": index})
        for index in range(1, optional_count + 1)
    )
    materials = [_format(item, context) for item in pack["materials"]]
    requirements = [_format(item, context) for item in pack["requirements"]]
    risks = [_format(item, context) for item in pack["risks"]]
    constraints = [_format(item, context) for item in pack["constraints"]]
    readiness = [_format(item, context) for item in pack["readiness"]]
    kpis = [_format(item, context) for item in pack["kpis"]]
    success = [_format(item, context) for item in pack["success"]]

    stage_keys = ("prototype", "mvp", "pilot", "production")
    stage_translation_keys = {
        "prototype": "concept.prototype",
        "mvp": "concept.mvp",
        "pilot": "concept.pilot",
        "production": "concept.production",
    }
    stage_names = {
        stage: translate(stage_translation_keys[stage], language)
        for stage in stage_keys
    }
    implementation_roadmap = {
        stage: _format(pack["roadmap"], {**context, "stage": stage_names[stage]})
        for stage in stage_keys
    }
    implementation_guides = {}
    for stage in stage_keys:
        stage_context = {**context, "stage": stage_names[stage]}
        architecture = [_format(item, stage_context) for item in pack["architecture"]]
        implementation_guides[stage] = {
            "execution_plan": {
                "goal": _format(pack["guide_goal"], stage_context),
                "steps": list(requirements),
                "specialists": [audience_text, pack["industries"][0], pack["industries"][1]],
                "technologies": list(materials),
                "estimated_budget": pack["budget"],
                "stage_risks": risks[:3],
                "readiness_criteria": list(readiness),
                "expected_output": _format(pack["expected"], stage_context),
            },
            "technical_architecture": {
                "system_schema": architecture[0],
                "module_interaction": architecture[1],
                "process_flow": architecture[2],
                "deployment_logic": architecture[3],
            },
            "resources_budget": {
                "team": [audience_text, pack["industries"][0], pack["industries"][1]],
                "stack": list(materials),
                "materials": list(materials),
                "cost_notes": pack["budget"],
            },
            "validation": {
                "tests": list(requirements),
                "kpi": list(kpis),
                "success_criteria": list(success),
            },
        }

    return {
        "title": f"{title_fragment} — {mode_label.title()} {concept_suffix}",
        "leonardo_concept": _format(pack["leonardo"], context),
        "leonardo_sketch_description": _format(pack["sketch"], context),
        "modern_product_name": f"{title_fragment} {pilot_suffix}",
        "modern_category": category_text,
        "executive_summary": _format(pack["summary"], context),
        "problem_statement": _format(pack["problem"], context),
        "target_users": [audience_text, *[_format(item, context) for item in pack["targets"]]],
        "industries": [category_text, *pack["industries"]],
        "use_cases": [_format(item, context) for item in pack["uses"]],
        "modern_principle": _format(pack["principle"], context),
        "system_components": components,
        "materials": materials,
        "technical_requirements": requirements,
        "modern_sketch_description": _format(pack["modern_sketch"], context),
        "implementation_roadmap": implementation_roadmap,
        "implementation_guides": implementation_guides,
        "deployment_strategy": _format(pack["deployment"], context),
        "risks": risks,
        "constraints": constraints,
        "market_demand": _format(pack["market"], context),
        "startup_cost": pack["startup"],
        "roi": pack["roi"],
        "investor_summary": _format(pack["investor"], context),
        "difficulty": pack["difficulties"].get(difficulty, difficulty),
        "modern_difficulty": pack["difficulties"].get(modern_difficulty, modern_difficulty),
        "dev_time": pack["dev_time"],
    }
